({ resume, activities, signatures, documents, process }) => {
    const candidateConditioning = (process.tramites.reverse().find((tramite)=>tramite.parecer_tecnico && tramite.parecer_tecnico.condicionantes_repeticao)||{}).parecer_tecnico.condicionantes_repeticao;
    const existingConditioning = (process.step.storage || {}).conditioning || [];
    const newConditioning = [];
    let i=0; 
    for(const conditioning of candidateConditioning) {
        const currentDeadline = conditioning.prazo_condicionantes_controle;
        if (!currentDeadline){
            continue;
        }
        const description = (conditioning.condicionantes_condicoes).replace(/<[^>]*>?/gm, '');		
	 let deadline = new Date(currentDeadline); 
 deadline.setUTCHours(23,59,59,999); 
 deadline.setHours(deadline.getHours() + 3) 
        const currentTopic = `parecer_tecnico/${i}`;

        const indexExistingConditioning = existingConditioning.findIndex(c => c.topic == currentTopic);
        const alreadyExist = indexExistingConditioning >= 0;

        const conditioningParams = {
            deadline, 
            topic: currentTopic,
            label: description, 
            description
        };

        if(alreadyExist) {
            updateConditioning(conditioningParams);
            existingConditioning.splice(indexExistingConditioning, 1);
        } else {
            createConditioning(conditioningParams);
        }

        newConditioning.push(conditioningParams);		
        i++;
    }

    for(const condToRemove of existingConditioning) {
        removeConditioning(condToRemove);
    }

    set({ conditioning: newConditioning })
}
